import JSON
using SpecialFunctions

"""
    gen( x, filepath )

Generate fixture data and write to file.

# Arguments

* `x`: domain
* `filepath::AbstractString`: filepath of output file

# Examples

``` julia
julia> x = range( -0.5, stop = 1.5, length = 2001 );
julia> gen( x, "./data.json" );
```
"""
function gen( x, filepath )
	x = collect( Float32.(x) );
	y = Float32.(SpecialFunctions.erfcinv.(x))
	
	# Handle -Inf values by replacing with large finite number
	for i in eachindex(y)
		if !isfinite( y[i] )
			y[i] = Float32( -5.805018901824951 );
		end
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("expected", y)
	]);

	# Write the data to output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# 0.5 <= x <= 1.5 (linear regime)
x = range( Float32(0.5), stop = Float32(1.5), length = 500 );
out = joinpath( dir, "x_0.5_1.5.json" );
gen( x, out );

# 0.25 < 2-x < 0.5
x = range( Float32(1.5), stop = Float32(1.75), length = 500 );
out = joinpath( dir, "x_1.5_1.75.json" );
gen( x, out );

# 0.25 < x < 0.5
x = range( Float32(0.25), stop = Float32(0.5), length = 500 );
out = joinpath( dir, "x_0.25_0.5.json" );
gen( x, out );

# 0.25 < 2-x < small
x = range( Float32(1.75), stop = Float32(1.9998), length = 500 );
out = joinpath( dir, "x_1.75_1.9998.json" );
gen( x, out );

# 0.0002 < x < 0.25
x = range( Float32(0.0002), stop = Float32(0.25), length = 500 );
out = joinpath( dir, "x_0.0002_0.25.json" );
gen( x, out );

# 0.00012340980408664937 < 2-x < 2.220446049250313e-16
x = range( 1.9998f0, stop = 1.9999999f0, length = 500 );
out = joinpath( dir, "x_1.9998_1.9999..8.json" );
gen( x, out );

# 2.220446049250313e-16 < 2-x < 0
x = range( 1.9999999f0, stop = 1.99999994f0, length = 500 );
out = joinpath( dir, "x_1.9999..8_2.json" );
gen( x, out );
